"""Record actual playable corridor coverage against independent named OSM geometry."""
import json,gzip,re,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
d=json.load(gzip.open(root/'docs/qa/world-blueprint/after-world.json.gz'));osm=json.load(open(root/'data/bangkok/osm-reference.v1.geojson'))['features']
norm=lambda s:re.sub(r'[^a-z0-9ก-๙]','',s.lower().replace('road','').replace('street',''))
aliases={'old_w':['Maha Rat','มหาราช'],'old_e':['Sanam Chai','สนามไชย'],'palace_n':['Na Phra Lan','หน้าพระลาน'],'old_siam':['Rama I','พระรามที่ 1'],'phaya':['Phahonyothin','Phaya Thai','พหลโยธิน','พญาไท'],'yaowarat':['Yaowarat','เยาวราช'],'tri-mit':['Tri Mit','ตรีมิตร'],'charoen_n':['Charoen Krung','เจริญกรุง'],'charoen_s':['Charoen Krung','เจริญกรุง'],'old_china':['Charoen Krung','เจริญกรุง'],'north_old':['Ratchadamnoen','ราชดำเนิน'],'sao-chingcha':['Bamrung Mueang','บำรุงเมือง'],'west':['Itsaraphap','อิสรภาพ'],'ratchadamri':['Ratchadamri','ราชดำริ'],'mangkon':['Mangkon','มังกร'],'plaeng-nam':['Plaeng Nam','แปลงนาม'],'songwat':['Song Wat','ทรงวาด'],'ratchawong':['Ratchawong','ราชวงศ์'],'sathorn':['Sathon','Sathorn','สาทร'],'ramaiv':['Rama IV','พระรามที่ 4'],'asok_ratchada':['Asok Montri','อโศกมนตรี'],'asok-north':['Asok Montri','อโศกมนตรี'],'sukhumvit-east':['Sukhumvit','สุขุมวิท'],'charoen_nakhon':['Charoen Nakhon','เจริญนคร'],'charoen-nakhon-south':['Charoen Nakhon','เจริญนคร'],'krung_thon_buri':['Krung Thon Buri','กรุงธนบุรี'],'ti-thong':['Ti Thong','ตีทอง'],'atsadang':['Atsadang','อัษฎางค์'],'dinso':['Dinso','ดินสอ'],'silom':['Si Lom','Silom','สีลม'],'narathiwas':['Naradhiwas','Narathiwat','นราธิวาส'],'thai-wang':['Thai Wang','ท้ายวัง']}
rows=[]
for c in sorted(set(r.get('corridor','') for r in d['roads'])):
 roads=[(i,r) for i,r in enumerate(d['roads']) if r.get('corridor','')==c];names=aliases.get(c,sorted(set(r['name'] for _,r in roads if r.get('name'))));hits=[]
 for f in osm:
  ns=[f['properties'].get(k,'') for k in ['name','name:en','name:th']]
  if any(norm(n) and norm(n) in norm(m) for n in names for m in ns):hits.append(f['id'])
 rows.append(dict(id=c,names=names,gameRoadIndices=[i for i,_ in roads],realGeometryReferences=hits,source='osm-reference.v1.geojson',status='named source geometry available; compressed alignment retained' if hits else 'arcade approval only; geographic comparison outstanding',compression='Lengths, widths and intersection spacing are authored, not literal GIS',oneWay=any(r.get('oneWay') for _,r in roads)))
lookup={'Ratchadamnoen':'north_old','Dinso':'dinso','Bamrung Mueang':'sao-chingcha','Sanam Chai':'old_e','Maha Rat':'old_w','Na Phra Lan':'palace_n','Ti Thong':'ti-thong','Atsadang':'atsadang','Yaowarat':'yaowarat','Charoen Krung':'charoen_n','Song Wat':'songwat','Ratchawong':'ratchawong','Mangkon':'mangkon','Plaeng Nam':'plaeng-nam','Tri Mit':'tri-mit','Rama I':'old_siam','Phaya Thai':'phaya','Ratchadamri':'ratchadamri','Phetchaburi':'phetchaburi','Sukhumvit':'sukhumvit','Asok Montri':'asok_ratchada','Phloen Chit':'sukhumvit','Sukhumvit Soi 11':'soi-11','Sukhumvit Soi 21':'asok_ratchada','Sukhumvit Soi 22':'soi-22','Sukhumvit Soi 24':'soi-24','Sukhumvit Soi 31':'soi-31','Sukhumvit Soi 39':'soi-39','Silom':'silom','Sathorn':'sathorn','Naradhiwas':'narathiwas','Rama IV':'ramaiv','Charoen Nakhon':'charoen_nakhon','Itsaraphap':'west','Krung Thon Buri':'krung_thon_buri','Phahonyothin':'phaya','Saphan Khwai':'phaya'}
required=list(lookup)+['Chak Phet','Phra Athit','Phadung Dao','Henri Dunant','Wireless','Surawong','Convent','Sala Daeng']
review=[dict(name=n,gameCorridor=lookup.get(n),status='present as compressed corridor; exact alignment pending' if n in lookup else 'missing separately named playable corridor') for n in required]
out=dict(schemaVersion=1,baseline='bangkok-arcade-2026.1',attribution='© OpenStreetMap contributors / ODbL 1.0',corridors=rows,requiredCorridorReview=review)
(root/'data/bangkok/street-audit.v1.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(len(rows),'corridors;',sum(bool(r['realGeometryReferences']) for r in rows),'have named source geometry;',len(required)-len(lookup),'requested named corridors absent')
